SELECT id, session_id, page, duration_sec, MAX(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_max_90d, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS row_seq, FIRST_VALUE(duration_sec) IGNORE NULLS OVER (PARTITION BY event_type, page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, LEAD(duration_sec, 1) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS next_duration_sec, LAST_VALUE(duration_sec) IGNORE NULLS OVER w_ordered AS last_known_duration_sec FROM web_events WHERE event_type IN ('add_to_cart', 'search') WINDOW w_ordered AS (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
